.pill-toggle-root {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: stretch;
  overflow: auto;
  font-family: "Segoe UI", system-ui, sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: geometricPrecision;
}
@supports (-moz-appearance: none) {
  .pill-toggle-root {
    scrollbar-width: thin;
    scrollbar-color: var(--pill-scrollbar-thumb, rgba(96, 94, 92, 0.55)) var(--pill-scrollbar-track, rgba(96, 94, 92, 0.12));
  }
}
.pill-toggle-root::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}
.pill-toggle-root::-webkit-scrollbar-thumb {
  background: var(--pill-scrollbar-thumb, rgba(96, 94, 92, 0.55));
  border-radius: 4px;
}
.pill-toggle-root::-webkit-scrollbar-track {
  background: var(--pill-scrollbar-track, rgba(96, 94, 92, 0.12));
}
.pill-toggle-root::-webkit-scrollbar-corner {
  background: transparent;
}
.pill-toggle-root .pill-toggle {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
  margin: auto 0;
}
.pill-toggle-root .pill-toggle.justify-center {
  justify-content: center;
  margin: auto;
}
.pill-toggle-root .pill-toggle.justify-right {
  justify-content: flex-end;
  margin: auto 0 auto auto;
}
.pill-toggle-root .pill-toggle.nowrap {
  flex-wrap: nowrap;
}
.pill-toggle-root .pill {
  padding: 4px 12px;
  border: 1px solid #C8C6C4;
  border-radius: 6px;
  background: #FFFFFF;
  color: #605E5C;
  cursor: pointer;
  font-family: inherit;
  line-height: 1.2;
  white-space: nowrap;
  transition: border-color 0.12s, background 0.12s, color 0.12s;
}
.pill-toggle-root .pill:hover {
  border-color: #1F908C;
}
.pill-toggle-root .pill.sel {
  font-weight: 600;
}
.pill-toggle-root.wrap .pill {
  white-space: normal;
  overflow-wrap: anywhere;
  text-align: left;
}
.pill-toggle-root .pill-landing {
  padding: 10px 12px;
  color: #605E5C;
  font-size: 11px;
}
.pill-toggle-root .pill-landing .pill-landing-title {
  font-size: 13px;
  font-weight: 700;
  color: #023864;
  margin-bottom: 3px;
}
.pill-toggle-root .pill-landing .pill-landing-body {
  line-height: 1.45;
}
.pill-toggle-root .pill:focus-visible {
  outline: 2px solid #1F908C;
  outline-offset: 1px;
}
